INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7263641, 1129952, 83313, '<td valign="top">I''d love to see the teeth of the person who ate this.</td>', 'I''d love to see the teeth of the person who ate this.', '2014-09-17 01:25:10.000000', NULL, 1),
(7263644, 1129984, 83313, '<td valign="top">Is speled <i>"dual"</i>. "duel" is fite to deth with leedur of enemy tribe. Gud for yu that Grog no takeaway points for spelling errurs.</td>', 'Is speled "dual". "duel" is fite to deth with leedur of enemy tribe. Gud for yu that Grog no takeaway points for spelling errurs.', '2014-09-17 01:30:10.000000', NULL, 1),
(7263675, 1129786, 97225, '<td valign="top">I really love this photo - and the Topaz processing. Enough to fave it, But... I don''t think that right angles produce the strength of the image.</td>', 'I really love this photo - and the Topaz processing. Enough to fave it, But... I don''t think that right angles produce the strength of the image.', '2014-09-17 02:59:33.000000', NULL, 1),
(7263676, 1129985, 97225, '<td valign="top">Lovely environmental portrait. Beautiful tones, awesome frame.</td>', 'Lovely environmental portrait. Beautiful tones, awesome frame.', '2014-09-17 03:01:31.000000', NULL, 1),
(7263677, 1129962, 97225, '<td valign="top">Oh, those eyes!</td>', 'Oh, those eyes!', '2014-09-17 03:03:13.000000', NULL, 1),
(7263681, 1129975, 97225, '<td valign="top">I think that if this had been presented in its natural orientation it would be a strong image that would meet the challenge well enough. I don''t think that the rotation has been kind to it.</td>', 'I think that if this had been presented in its natural orientation it would be a strong image that would meet the challenge well enough. I don''t think that the rotation has been kind to it.', '2014-09-17 03:15:29.000000', NULL, 1),
(7263683, 1129923, 97225, '<td valign="top">Very op art. Looks like a view through crates. Great entry. 10</td>', 'Very op art. Looks like a view through crates. Great entry. 10', '2014-09-17 03:17:30.000000', NULL, 1),
(7263684, 1129950, 97225, '<td valign="top">Nice colours and textures in the stone.</td>', 'Nice colours and textures in the stone.', '2014-09-17 03:24:21.000000', NULL, 1),
(7263685, 1129683, 141826, '<td valign="top">10++<br/> <br/>Just voted...</td>', '10++ Just voted...', '2014-09-17 03:28:50.000000', NULL, 1),
(7263692, 1129797, 163430, '<td valign="top">Interesting. Both curvy and edgy. I like it.<br/>I wonder whether the colour (dis)balance on the different floors was intentional or unavoidable. I would have went with black and white.</td>', 'Interesting. Both curvy and edgy. I like it.I wonder whether the colour (dis)balance on the different floors was intentional or unavoidable. I would have went with black and white.', '2014-09-17 04:55:18.000000', NULL, 1),
(7263693, 1129923, 163430, '<td valign="top">Lots of right angles here.<br/>I like the graphiqueness (is this even a word?) of the whole image.</td>', 'Lots of right angles here.I like the graphiqueness (is this even a word?) of the whole image.', '2014-09-17 05:05:40.000000', NULL, 1),
(7263694, 1129547, 163430, '<td valign="top">That logo in the lower right corner is a basis for a DQ :-(</td>', 'That logo in the lower right corner is a basis for a DQ :-(', '2014-09-17 05:10:13.000000', NULL, 1),
(7263695, 1129976, 163430, '<td valign="top">Interesting play of shadows, structure and right angles.<br/>A bit too soft and overprocessed for my taste.</td>', 'Interesting play of shadows, structure and right angles.A bit too soft and overprocessed for my taste.', '2014-09-17 05:12:09.000000', NULL, 1),
(7263696, 1129982, 163430, '<td valign="top">Interesting. Implied right angles.</td>', 'Interesting. Implied right angles.', '2014-09-17 05:19:20.000000', NULL, 1),
(7263697, 1129984, 163430, '<td valign="top">Interesting idea, but the photographic execution is under par. Too soft, too grainy and the lines are crooked.</td>', 'Interesting idea, but the photographic execution is under par. Too soft, too grainy and the lines are crooked.', '2014-09-17 05:33:23.000000', NULL, 1),
(7263722, 1129990, 153814, '<td valign="top">Yes yes yes!!! To me you nailed it. The feel good image of the challenge and my only 10. Very well done.</td>', 'Yes yes yes!!! To me you nailed it. The feel good image of the challenge and my only 10. Very well done.', '2014-09-17 08:53:29.000000', NULL, 1),
(7263724, 1129954, 153814, '<td valign="top">One of my top picks, the wood grain really pops. <br/>Perfect angles and composition. Well done.</td>', 'One of my top picks, the wood grain really pops. Perfect angles and composition. Well done.', '2014-09-17 08:55:46.000000', NULL, 1),
(7263726, 1129692, 153814, '<td valign="top">Talk about unique! One of my top picks. I just wish there was more constrast with the right angles. Still gave it a 9. Well done.</td>', 'Talk about unique! One of my top picks. I just wish there was more constrast with the right angles. Still gave it a 9. Well done.', '2014-09-17 08:58:05.000000', NULL, 1),
(7263728, 1129547, 77543, '<td valign="top">oops text</td>', 'oops text', '2014-09-17 09:05:30.000000', NULL, 1),
(7263742, 1129851, 13077, '<td valign="top">Simple and effective.</td>', 'Simple and effective.', '2014-09-17 11:51:06.000000', NULL, 1),
(7263744, 1129982, 30861, '<td valign="top">This is fantastic. I voted last night, gave it an 8. Implied right angles, awesome. I assume you''re getting hammered, though?</td>', 'This is fantastic. I voted last night, gave it an 8. Implied right angles, awesome. I assume you''re getting hammered, though?', '2014-09-17 12:10:11.000000', NULL, 1),
(7263745, 1129683, 16046, '<td valign="top">Best in show award, congrats</td>', 'Best in show award, congrats', '2014-09-17 12:18:25.000000', NULL, 1),
(7263746, 1129895, 16046, '<td valign="top">Top 3</td>', 'Top 3', '2014-09-17 12:18:39.000000', NULL, 1),
(7263747, 1129938, 16046, '<td valign="top">Top 3</td>', 'Top 3', '2014-09-17 12:19:19.000000', NULL, 1),
(7263748, 1129902, 16046, '<td valign="top">Front page stuff</td>', 'Front page stuff', '2014-09-17 12:19:41.000000', NULL, 1),
(7263754, 1129870, 13077, '<td valign="top">Interesting angle of view and good choice of crop.</td>', 'Interesting angle of view and good choice of crop.', '2014-09-17 12:35:17.000000', NULL, 1),
(7263755, 1129950, 13077, '<td valign="top">Good textures on the wall, and well composed. The sharpening looks a little extreme, though, and a bit more contrast might have helped.</td>', 'Good textures on the wall, and well composed. The sharpening looks a little extreme, though, and a bit more contrast might have helped.', '2014-09-17 12:40:12.000000', NULL, 1),
(7263757, 1129835, 13077, '<td valign="top">Great architecture details and perfectly exposed. Full of angles of all kinds.</td>', 'Great architecture details and perfectly exposed. Full of angles of all kinds.', '2014-09-17 12:40:49.000000', NULL, 1),
(7263759, 1129987, 13077, '<td valign="top">Was that motor boat escorting the canoe? I think I would have prefered it with just the canoe, but nicely framed and good light. A wider crop could probably have helped as well.</td>', 'Was that motor boat escorting the canoe? I think I would have prefered it with just the canoe, but nicely framed and good light. A wider crop could probably have helped as well.', '2014-09-17 12:41:59.000000', NULL, 1),
(7263762, 1129900, 13077, '<td valign="top">Interesting reflections and overall environment. I probably would have cropped out the bridge support on the left, though.</td>', 'Interesting reflections and overall environment. I probably would have cropped out the bridge support on the left, though.', '2014-09-17 12:43:33.000000', NULL, 1),
(7263765, 1129956, 13077, '<td valign="top">Cool - not too many right angles in nature, well captured.<br/>Good job keeping detail in the black bear without overexposing the rest.</td>', 'Cool - not too many right angles in nature, well captured.Good job keeping detail in the black bear without overexposing the rest.', '2014-09-17 12:45:07.000000', NULL, 1),
(7263770, 1129938, 13077, '<td valign="top">It does have a right angle, but it strikes me as a very small element of the photo. The photo itself doesn''t have many interesting aspects either, in my opinion.</td>', 'It does have a right angle, but it strikes me as a very small element of the photo. The photo itself doesn''t have many interesting aspects either, in my opinion.', '2014-09-17 12:48:52.000000', NULL, 1),
(7263771, 1129921, 13077, '<td valign="top">There''s something that feels awkward either about the way it''s composed, the way they are arranged, or maybe both.</td>', 'There''s something that feels awkward either about the way it''s composed, the way they are arranged, or maybe both.', '2014-09-17 12:49:49.000000', NULL, 1),
(7263773, 1129753, 13077, '<td valign="top">Good point, well illustrated.</td>', 'Good point, well illustrated.', '2014-09-17 12:50:24.000000', NULL, 1),
(7263788, 1129954, 12733, '<td valign="top">Great textures and an interesting concept.</td>', 'Great textures and an interesting concept.', '2014-09-17 13:06:27.000000', NULL, 1),
(7263789, 1129692, 12733, '<td valign="top">The most relevant angles are not right angles at all. The animals look as if they''ve been guillotined.</td>', 'The most relevant angles are not right angles at all. The animals look as if they''ve been guillotined.', '2014-09-17 13:08:57.000000', NULL, 1),
(7263791, 1129704, 12733, '<td valign="top">I like the stark look of this picture and the contrast of the right angles with the curved windows</td>', 'I like the stark look of this picture and the contrast of the right angles with the curved windows', '2014-09-17 13:10:16.000000', NULL, 1),
(7263793, 1129984, 12733, '<td valign="top">Wow!</td>', 'Wow!', '2014-09-17 13:11:09.000000', NULL, 1),
(7263794, 1129786, 12733, '<td valign="top">Great animal, great landscape, but the few right angles get lost in all the natural curves and angles.</td>', 'Great animal, great landscape, but the few right angles get lost in all the natural curves and angles.', '2014-09-17 13:12:46.000000', NULL, 1),
(7263795, 1129936, 12733, '<td valign="top">Other than the corners of the square, where are the right angles in this picture?</td>', 'Other than the corners of the square, where are the right angles in this picture?', '2014-09-17 13:13:30.000000', NULL, 1),
(7263796, 1129957, 12733, '<td valign="top">fantastic angle; draws the eye straight up.</td>', 'fantastic angle; draws the eye straight up.', '2014-09-17 13:14:06.000000', NULL, 1),
(7263797, 1129835, 12733, '<td valign="top">The effect is dizzying. Great shot.</td>', 'The effect is dizzying. Great shot.', '2014-09-17 13:15:06.000000', NULL, 1),
(7263798, 1129976, 12733, '<td valign="top">nice texture shot.</td>', 'nice texture shot.', '2014-09-17 13:16:04.000000', NULL, 1),
(7263799, 1129782, 12733, '<td valign="top">Nice texture on the dock. A very peaceful scene.</td>', 'Nice texture on the dock. A very peaceful scene.', '2014-09-17 13:18:38.000000', NULL, 1),
(7263800, 1129916, 12733, '<td valign="top">A very confused scene, and the right angle is hard to pick out of the jumble.</td>', 'A very confused scene, and the right angle is hard to pick out of the jumble.', '2014-09-17 13:19:39.000000', NULL, 1),
(7263801, 1129952, 12733, '<td valign="top">Contrived looking, and over bright. Nice idea, but it doesn''t work for me.</td>', 'Contrived looking, and over bright. Nice idea, but it doesn''t work for me.', '2014-09-17 13:21:02.000000', NULL, 1),
(7263802, 1129927, 12733, '<td valign="top">I don''t know why this picture appeals, but it does.</td>', 'I don''t know why this picture appeals, but it does.', '2014-09-17 13:22:02.000000', NULL, 1),
(7263803, 1129693, 12733, '<td valign="top">Too abstract, and I don''t really see the right angles, though I can tell they''re there after searching.</td>', 'Too abstract, and I don''t really see the right angles, though I can tell they''re there after searching.', '2014-09-17 13:23:16.000000', NULL, 1),
(7263804, 1129957, 60173, '<td valign="top">With the sky being blown, this might have looked better in B&amp;W. Great perspective though, and certainly fits the challenge.</td>', 'With the sky being blown, this might have looked better in B&W. Great perspective though, and certainly fits the challenge.', '2014-09-17 13:48:17.000000', NULL, 1),
(7263805, 1129936, 60173, '<td valign="top">I can''t honestly say that I see a right angle on this leaf. I see angles, but none of them are 90 degrees.</td>', 'I can''t honestly say that I see a right angle on this leaf. I see angles, but none of them are 90 degrees.', '2014-09-17 13:52:57.000000', NULL, 1),
(7263806, 1129975, 60173, '<td valign="top">This would have scored far better if it weren''t rotated.</td>', 'This would have scored far better if it weren''t rotated.', '2014-09-17 13:54:56.000000', NULL, 1),
(7263807, 1129692, 60173, '<td valign="top">I see many right angles, but I don''t feel that they are the focal point of this photo. With that said, I really like the image, just not for this challenge.</td>', 'I see many right angles, but I don''t feel that they are the focal point of this photo. With that said, I really like the image, just not for this challenge.', '2014-09-17 13:56:13.000000', NULL, 1),
(7263808, 1129990, 60173, '<td valign="top">Cute image, but I''d like it to have stronger focus on his face.</td>', 'Cute image, but I''d like it to have stronger focus on his face.', '2014-09-17 13:58:04.000000', NULL, 1),
(7263810, 1129984, 60173, '<td valign="top">The execution of the paper placement needs to be better. You also have a dark area in the lower right. Images like this need to be pristine, in my opinion.</td>', 'The execution of the paper placement needs to be better. You also have a dark area in the lower right. Images like this need to be pristine, in my opinion.', '2014-09-17 13:59:39.000000', NULL, 1),
(7263812, 1129942, 60173, '<td valign="top">I like the angles, reflection, and lighting. Definitely a quality shot, but it''s quite boring though to be honest. Like you said, it''s a "thingamajig". If you don''t know what it is, neither do I, heh.</td>', 'I like the angles, reflection, and lighting. Definitely a quality shot, but it''s quite boring though to be honest. Like you said, it''s a "thingamajig". If you don''t know what it is, neither do I, heh.', '2014-09-17 14:01:54.000000', NULL, 1),
(7263813, 1129797, 60173, '<td valign="top">This is a nice image, but I don''t feel like the right angles are really the subject here. Sure, I see right angles on the railing and in the lighting, but that spiral is just too much to contend with.</td>', 'This is a nice image, but I don''t feel like the right angles are really the subject here. Sure, I see right angles on the railing and in the lighting, but that spiral is just too much to contend with.', '2014-09-17 14:02:54.000000', NULL, 1),
(7263814, 1129738, 12733, '<td valign="top">Striking colors!</td>', 'Striking colors!', '2014-09-17 14:03:29.000000', NULL, 1),
(7263815, 1129966, 60173, '<td valign="top">I like your composition. I wish the focus were better, but overall it has a great feel.</td>', 'I like your composition. I wish the focus were better, but overall it has a great feel.', '2014-09-17 14:04:22.000000', NULL, 1),
(7263816, 1129956, 12733, '<td valign="top">Nice shot of a bear, but it doesn''t seem to suit this theme.</td>', 'Nice shot of a bear, but it doesn''t seem to suit this theme.', '2014-09-17 14:04:30.000000', NULL, 1),
(7263817, 1129938, 60173, '<td valign="top">The right angle in this photo is subtle and somewhat unexpected. I likes.</td>', 'The right angle in this photo is subtle and somewhat unexpected. I likes.', '2014-09-17 14:06:08.000000', NULL, 1),
(7263818, 1129728, 12733, '<td valign="top">Interesting take on right angles, though technically those wings are a bit more than 90 degrees.</td>', 'Interesting take on right angles, though technically those wings are a bit more than 90 degrees.', '2014-09-17 14:07:02.000000', NULL, 1),
(7263819, 1129975, 12733, '<td valign="top">and sideways, too. An interesting building, but I don''t see why turning it sideways adds anything.</td>', 'and sideways, too. An interesting building, but I don''t see why turning it sideways adds anything.', '2014-09-17 14:08:40.000000', NULL, 1),
(7263820, 1129749, 60173, '<td valign="top">While I like this image, it''s a photo of a "thing", especially when they''re shot straight on. It''s hard to make a "thing" your own, ya know? Like, what makes this photo any different than the next photographer that stumbles across it?</td>', 'While I like this image, it''s a photo of a "thing", especially when they''re shot straight on. It''s hard to make a "thing" your own, ya know? Like, what makes this photo any different than the next photographer that stumbles across it?', '2014-09-17 14:10:45.000000', NULL, 1),
(7263821, 1129966, 12733, '<td valign="top">Are these all corks? An interesting bit of whimsey.</td>', 'Are these all corks? An interesting bit of whimsey.', '2014-09-17 14:10:57.000000', NULL, 1),
(7263822, 1129945, 60173, '<td valign="top">The composition feels off balance to me. I do like the lighting and softness of the whole thing.</td>', 'The composition feels off balance to me. I do like the lighting and softness of the whole thing.', '2014-09-17 14:12:08.000000', NULL, 1),
(7263823, 1129979, 12733, '<td valign="top">Some focus might make this shot - like having the stone really sharp and the background blurry. But the main subject does need to be sharp.</td>', 'Some focus might make this shot - like having the stone really sharp and the background blurry. But the main subject does need to be sharp.', '2014-09-17 14:12:49.000000', NULL, 1),
(7263824, 1129914, 60173, '<td valign="top">Cute. <br/> <br/>I probably would have gone with a square crop of this. Granted, that wouldn''t work if you took a square crop from the image you submitted here. The crop cuts off at about the wall edge (I tried). So, I guess, it would depend on what was in the top and bottom that have since been cut off.</td>', 'Cute.  I probably would have gone with a square crop of this. Granted, that wouldn''t work if you took a square crop from the image you submitted here. The crop cuts off at about the wall edge (I tried). So, I guess, it would depend on what was in the top and bottom that have since been cut off.', '2014-09-17 14:16:26.000000', NULL, 1),
(7263825, 1129902, 60173, '<td valign="top">Very strong composition that I like very much. I think I could have done without the person or perhaps something more aesthetic than flip-flops. I also think you''ve gone a bit dark overall. My gut tells me that the floor should have more white crispiness or something. Seems quite muddled.</td>', 'Very strong composition that I like very much. I think I could have done without the person or perhaps something more aesthetic than flip-flops. I also think you''ve gone a bit dark overall. My gut tells me that the floor should have more white crispiness or something. Seems quite muddled.', '2014-09-17 14:18:57.000000', NULL, 1),
(7263826, 1129738, 60173, '<td valign="top">Those are some bold colors; bold colors that are all very easy to over-expose. Nice job keeping them in check.</td>', 'Those are some bold colors; bold colors that are all very easy to over-expose. Nice job keeping them in check.', '2014-09-17 14:19:48.000000', NULL, 1),
(7263827, 1129963, 60173, '<td valign="top">I like the mood you have created with your lighting.</td>', 'I like the mood you have created with your lighting.', '2014-09-17 14:28:48.000000', NULL, 1),
(7263828, 1129982, 60173, '<td valign="top">Without the title, I wouldn''t have "connected the dots."</td>', 'Without the title, I wouldn''t have "connected the dots."', '2014-09-17 14:31:27.000000', NULL, 1),
(7263829, 1129964, 60173, '<td valign="top">I don''t feel that the shapes are strong enough on their own to be a silhouette. Without the strong shapes, this just becomes an underexposed image.</td>', 'I don''t feel that the shapes are strong enough on their own to be a silhouette. Without the strong shapes, this just becomes an underexposed image.', '2014-09-17 14:32:40.000000', NULL, 1),
(7263830, 1129925, 60173, '<td valign="top">The Photoshop filter doesn''t do much to help here. It actually makes the pixel quality seem really bad, because I first saw the texture as color banding.</td>', 'The Photoshop filter doesn''t do much to help here. It actually makes the pixel quality seem really bad, because I first saw the texture as color banding.', '2014-09-17 14:33:40.000000', NULL, 1),
(7263831, 1129946, 60173, '<td valign="top">Yup, it''s a chair. Does this chair have a purpose? I can''t see why you''re showing me this photo of a chair in the shadows. The highlights of your bush on the lower left are also over exposed.</td>', 'Yup, it''s a chair. Does this chair have a purpose? I can''t see why you''re showing me this photo of a chair in the shadows. The highlights of your bush on the lower left are also over exposed.', '2014-09-17 14:35:14.000000', NULL, 1),
(7263833, 1129728, 60173, '<td valign="top">The big blurry flower on the left needs to go away. It has a really strong presence in the photo, and detracts from the beautiful butterfly. Overall, I think the image is under exposed. I see the right angle in the wings though!</td>', 'The big blurry flower on the left needs to go away. It has a really strong presence in the photo, and detracts from the beautiful butterfly. Overall, I think the image is under exposed. I see the right angle in the wings though!', '2014-09-17 14:36:51.000000', NULL, 1),
(7263834, 1129892, 60173, '<td valign="top">It''s a nice image, but I don''t get "right angle" from it.</td>', 'It''s a nice image, but I don''t get "right angle" from it.', '2014-09-17 14:37:42.000000', NULL, 1),
(7263835, 1129831, 60173, '<td valign="top">Gotta be honest, don''t like the composition at all. The top of the board makes a nice leading line to the corner, but your poor bee is just plopped there in the middle. The bee isn''t big enough or in enough focus to carry the weight of where he is.</td>', 'Gotta be honest, don''t like the composition at all. The top of the board makes a nice leading line to the corner, but your poor bee is just plopped there in the middle. The bee isn''t big enough or in enough focus to carry the weight of where he is.', '2014-09-17 14:39:38.000000', NULL, 1),
(7263836, 1129921, 60173, '<td valign="top">Entries of paper really don''t do anything for me. When I do see them in challenges, I expect damn near perfection, because really, you''re just taking a straight on shot of paper on a table, ya know?<br/> <br/>I like the shadows under the edges that show definition, but the overall lighting isn''t even. The right side is much darker than the left side. Also, the composition is off center. The placement doesn''t seem purposeful. I feel that it needs to be totally square and balanced or turned to one side enough to feel intentional.</td>', 'Entries of paper really don''t do anything for me. When I do see them in challenges, I expect damn near perfection, because really, you''re just taking a straight on shot of paper on a table, ya know? I like the shadows under the edges that show definition, but the overall lighting isn''t even. The right side is much darker than the left side. Also, the composition is off center. The placement doesn''t seem purposeful. I feel that it needs to be totally square and balanced or turned to one side enough to feel intentional.', '2014-09-17 14:44:24.000000', NULL, 1),
(7263837, 1129786, 60173, '<td valign="top">I like this, but I can''t honestly say I feel it fits the challenge. Sure, there''s right angles in there, but they all seem coincidental.</td>', 'I like this, but I can''t honestly say I feel it fits the challenge. Sure, there''s right angles in there, but they all seem coincidental.', '2014-09-17 14:45:50.000000', NULL, 1),
(7263838, 1129935, 60173, '<td valign="top">Angels? As in the things from the heavens? That seems to be the only explanation I can find as to why 3/4 of your image is blown out fuzzy white.  :/</td>', 'Angels? As in the things from the heavens? That seems to be the only explanation I can find as to why 3/4 of your image is blown out fuzzy white.  :/', '2014-09-17 14:47:12.000000', NULL, 1),
(7263839, 1129916, 60173, '<td valign="top">I see a pretty square rock in there, but as a photographer, you''ve done nothing to direct me to it. Overall, the image is very over exposed.</td>', 'I see a pretty square rock in there, but as a photographer, you''ve done nothing to direct me to it. Overall, the image is very over exposed.', '2014-09-17 14:48:05.000000', NULL, 1),
(7263840, 1129586, 60173, '<td valign="top">I bet this is a pretty cool place to walk through; like an overgrown Labyrinth. Since I do see some Labyrinth qualities, I can forgive the horizon tilt. Much more needs to be done with lighting to make this truly interesting though, and I don''t see the right angles.</td>', 'I bet this is a pretty cool place to walk through; like an overgrown Labyrinth. Since I do see some Labyrinth qualities, I can forgive the horizon tilt. Much more needs to be done with lighting to make this truly interesting though, and I don''t see the right angles.', '2014-09-17 14:49:55.000000', NULL, 1),
(7263841, 1129956, 60173, '<td valign="top">I see a really cute, fluffy bear, but I don''t see the right angles.</td>', 'I see a really cute, fluffy bear, but I don''t see the right angles.', '2014-09-17 14:51:25.000000', NULL, 1),
(7263842, 1129962, 60173, '<td valign="top">I actually didn''t see the cookies the first couple times I looked at this image. Overall, there seems to be a slight motion blur that is distracting me, I think.</td>', 'I actually didn''t see the cookies the first couple times I looked at this image. Overall, there seems to be a slight motion blur that is distracting me, I think.', '2014-09-17 14:53:01.000000', NULL, 1),
(7263843, 1129896, 60173, '<td valign="top">Right angles aren''t the subject of this photo. Perhaps framing him in a parking spot or something. As it is now, I struggle to find what right angle you''re trying to show me.</td>', 'Right angles aren''t the subject of this photo. Perhaps framing him in a parking spot or something. As it is now, I struggle to find what right angle you''re trying to show me.', '2014-09-17 14:54:36.000000', NULL, 1),
(7263844, 1129583, 60173, '<td valign="top">I see lots of right angles, but I don''t have any context that shows me what it is that I''m looking at.</td>', 'I see lots of right angles, but I don''t have any context that shows me what it is that I''m looking at.', '2014-09-17 14:55:17.000000', NULL, 1),
(7263845, 1129913, 60173, '<td valign="top">Overall, it''s a little flat. Looking through the narrow opening also makes me feel nervous. I almost feel like I''m gonna get stuck somehow, even though it''s just a photo. Ahhh, let me out!<br/> <br/>...I like the leading lines coming from (or going to) the left corners.</td>', 'Overall, it''s a little flat. Looking through the narrow opening also makes me feel nervous. I almost feel like I''m gonna get stuck somehow, even though it''s just a photo. Ahhh, let me out! ...I like the leading lines coming from (or going to) the left corners.', '2014-09-17 14:57:57.000000', NULL, 1),
(7263846, 1129572, 60173, '<td valign="top">The lighting is interesting, and it appears mostly in focus. However, it''s a bracket... on a wall. Can''t say that really excites me, heh.</td>', 'The lighting is interesting, and it appears mostly in focus. However, it''s a bracket... on a wall. Can''t say that really excites me, heh.', '2014-09-17 14:58:50.000000', NULL, 1),
(7263847, 1129937, 60173, '<td valign="top">The fence is painfully out of focus.</td>', 'The fence is painfully out of focus.', '2014-09-17 14:59:14.000000', NULL, 1),
(7263848, 1129895, 60173, '<td valign="top">I don''t like the vignette. <br/> <br/>There''s a way to make this madness of cables and wires look great, but I''m not sure this is it. I wish I could tell you how I might improve it, but this is a tough one. I sort of feel like you''re on the wrong side of the boats. We''re looking at the shadow side rather than the side that''s lit. Maybe that would help bring definition to the chaos?</td>', 'I don''t like the vignette.  There''s a way to make this madness of cables and wires look great, but I''m not sure this is it. I wish I could tell you how I might improve it, but this is a tough one. I sort of feel like you''re on the wrong side of the boats. We''re looking at the shadow side rather than the side that''s lit. Maybe that would help bring definition to the chaos?', '2014-09-17 15:02:11.000000', NULL, 1),
(7263849, 1129801, 60173, '<td valign="top">I can fully appreciate the composition, but the time of day is really killing this for me. The magic of this place certainly isn''t at its best in the middle of the afternoon, heh.</td>', 'I can fully appreciate the composition, but the time of day is really killing this for me. The magic of this place certainly isn''t at its best in the middle of the afternoon, heh.', '2014-09-17 15:05:45.000000', NULL, 1),
(7263850, 1129958, 60173, '<td valign="top">I gotta wonder what mad carpenter built this crazy corner.</td>', 'I gotta wonder what mad carpenter built this crazy corner.', '2014-09-17 15:09:49.000000', NULL, 1),
(7263851, 1129970, 60173, '<td valign="top">I can tell there''s some texture on the blue surface, but otherwise, I think this has gone too graphical for a photography challenge.</td>', 'I can tell there''s some texture on the blue surface, but otherwise, I think this has gone too graphical for a photography challenge.', '2014-09-17 15:10:52.000000', NULL, 1),
(7263853, 1129976, 60173, '<td valign="top">I like seeing the grain texture on these ends. I don''t like the shadow from above though. I think a square crop for this image was a good choice.</td>', 'I like seeing the grain texture on these ends. I don''t like the shadow from above though. I think a square crop for this image was a good choice.', '2014-09-17 15:12:23.000000', NULL, 1),
(7263854, 1129694, 60173, '<td valign="top">I don''t like the contrasty processing here; especially in the sky. Also, while I truly believe that there''s a lot of right angles going on in that red structure, I don''t think you''ve brought enough attention to them in this photo.</td>', 'I don''t like the contrasty processing here; especially in the sky. Also, while I truly believe that there''s a lot of right angles going on in that red structure, I don''t think you''ve brought enough attention to them in this photo.', '2014-09-17 15:15:51.000000', NULL, 1),
(7263855, 1129961, 60173, '<td valign="top">Love the reflections on the building. I believe this could really benefit from some selective color/brightness/contrast adjusting.</td>', 'Love the reflections on the building. I believe this could really benefit from some selective color/brightness/contrast adjusting.', '2014-09-17 15:17:40.000000', NULL, 1),
(7263856, 1129987, 60173, '<td valign="top">Not the greatest challenge for this scene. I hope you got a few without the fence in the way. Looks like some beautiful light.</td>', 'Not the greatest challenge for this scene. I hope you got a few without the fence in the way. Looks like some beautiful light.', '2014-09-17 15:19:08.000000', NULL, 1),
(7263857, 1129900, 60173, '<td valign="top">Quality light and a lovely scene. I''m not totally sold on the "right angle" bit, but I do see them in there. It''s really interesting how the reflection of the fence in the water almost gets techy. Kind of looks like graph paper.</td>', 'Quality light and a lovely scene. I''m not totally sold on the "right angle" bit, but I do see them in there. It''s really interesting how the reflection of the fence in the water almost gets techy. Kind of looks like graph paper.', '2014-09-17 15:20:26.000000', NULL, 1),
(7263858, 1129811, 60173, '<td valign="top">Not entirely sure what I''m looking at, but I kind of dig it.</td>', 'Not entirely sure what I''m looking at, but I kind of dig it.', '2014-09-17 15:20:51.000000', NULL, 1),
(7263860, 1129899, 60173, '<td valign="top">I don''t see anything terribly unique about this photo. I guess without your processing it would be even more ho-hum. It''s unfortunately easily forgotten still.</td>', 'I don''t see anything terribly unique about this photo. I guess without your processing it would be even more ho-hum. It''s unfortunately easily forgotten still.', '2014-09-17 15:22:19.000000', NULL, 1),
