(7264146, 1129984, 13077, '<td valign="top">It''s vibrant and there''s lots of right angles, but I''m not crazy for the gaps between the squares.</td>', 'It''s vibrant and there''s lots of right angles, but I''m not crazy for the gaps between the squares.', '2014-09-18 19:39:08.000000', NULL, 1),
(7264147, 1129966, 13077, '<td valign="top">Nicely composed and the various logos and textures work well together. Would make a good print.</td>', 'Nicely composed and the various logos and textures work well together. Would make a good print.', '2014-09-18 19:39:56.000000', NULL, 1),
(7264149, 1129696, 13077, '<td valign="top">I don''t get the title or the relation to the challenge topic.</td>', 'I don''t get the title or the relation to the challenge topic.', '2014-09-18 19:40:21.000000', NULL, 1),
(7264151, 1129583, 13077, '<td valign="top">Nice title, simple portrayal of an interesting subject, and well lit and exposed.</td>', 'Nice title, simple portrayal of an interesting subject, and well lit and exposed.', '2014-09-18 19:44:54.000000', NULL, 1),
(7264152, 1129844, 13077, '<td valign="top">Nicely composed, good exposure and meets the challenge well.</td>', 'Nicely composed, good exposure and meets the challenge well.', '2014-09-18 19:45:15.000000', NULL, 1),
(7264153, 1129975, 13077, '<td valign="top">Bold decision to rotate it that way, but it''s pretty cool in my opinion.</td>', 'Bold decision to rotate it that way, but it''s pretty cool in my opinion.', '2014-09-18 19:45:55.000000', NULL, 1),
(7264154, 1129952, 13077, '<td valign="top">Never thought an apple would have right angles, but this one sure does. lol</td>', 'Never thought an apple would have right angles, but this one sure does. lol', '2014-09-18 19:46:18.000000', NULL, 1),
(7264155, 1129954, 13077, '<td valign="top">I still like this one, the textures are really well presented and it does meet the challenge for sure.</td>', 'I still like this one, the textures are really well presented and it does meet the challenge for sure.', '2014-09-18 19:47:01.000000', NULL, 1),
(7264156, 1129964, 13077, '<td valign="top">Having most of the photo in shadow doesn''t really work too well with a wide angle shot like this in my opinion.</td>', 'Having most of the photo in shadow doesn''t really work too well with a wide angle shot like this in my opinion.', '2014-09-18 19:47:32.000000', NULL, 1),
(7264157, 1129896, 13077, '<td valign="top">The right angles seem pretty distant and inconsequential here.</td>', 'The right angles seem pretty distant and inconsequential here.', '2014-09-18 19:48:02.000000', NULL, 1),
(7264158, 1129831, 13077, '<td valign="top">Not bad, and it does have a right angle, but I''m not crazy about showing so much of the flat wooden surface with the same texture, combined with the angle of the photo.</td>', 'Not bad, and it does have a right angle, but I''m not crazy about showing so much of the flat wooden surface with the same texture, combined with the angle of the photo.', '2014-09-18 19:49:26.000000', NULL, 1),
(7264160, 1129811, 13077, '<td valign="top">Interesting patterns and textures.</td>', 'Interesting patterns and textures.', '2014-09-18 19:52:20.000000', NULL, 1),
(7264161, 1129895, 13077, '<td valign="top">Nice - full of all sorts of angles and sharp throughout, the clouds are pleasant as well.</td>', 'Nice - full of all sorts of angles and sharp throughout, the clouds are pleasant as well.', '2014-09-18 19:53:11.000000', NULL, 1),
(7264162, 1129936, 13077, '<td valign="top">They aren''t quite right angles, but as far as nature goes they are close, and it''s a nicely done leaf detail shot for the most part.</td>', 'They aren''t quite right angles, but as far as nature goes they are close, and it''s a nicely done leaf detail shot for the most part.', '2014-09-18 19:53:51.000000', NULL, 1),
(7264163, 1129693, 13077, '<td valign="top">Kinda, Sorta, I guess... but there''s not much going for the photo overall.</td>', 'Kinda, Sorta, I guess... but there''s not much going for the photo overall.', '2014-09-18 19:54:15.000000', NULL, 1),
(7264164, 1129957, 13077, '<td valign="top">Meets the challenge and full of cool textures and a nice perspective.</td>', 'Meets the challenge and full of cool textures and a nice perspective.', '2014-09-18 19:54:40.000000', NULL, 1),
(7264165, 1129914, 13077, '<td valign="top">Nicely lit, meets the challenge, and well placed focus.</td>', 'Nicely lit, meets the challenge, and well placed focus.', '2014-09-18 20:00:21.000000', NULL, 1),
(7264166, 1129922, 13077, '<td valign="top">Nicely set up and I like the tone you gave it.</td>', 'Nicely set up and I like the tone you gave it.', '2014-09-18 20:02:34.000000', NULL, 1),
(7264168, 1129704, 13077, '<td valign="top">Very cool. Nice light and great job keeping the shaded portions well exposed.</td>', 'Very cool. Nice light and great job keeping the shaded portions well exposed.', '2014-09-18 20:05:31.000000', NULL, 1),
(7264169, 1129963, 13077, '<td valign="top">Nice dramatic lighting and well presented textures and patterns. I wonder if the position of those pawns could happen in a game though?</td>', 'Nice dramatic lighting and well presented textures and patterns. I wonder if the position of those pawns could happen in a game though?', '2014-09-18 20:07:52.000000', NULL, 1),
(7264170, 1129961, 13077, '<td valign="top">Meets the challenge, and I like how the building darkens the sky and it shows just a little bit of the tree in the light and the rest is reflected in shadow. Really interesting overall.</td>', 'Meets the challenge, and I like how the building darkens the sky and it shows just a little bit of the tree in the light and the rest is reflected in shadow. Really interesting overall.', '2014-09-18 20:08:58.000000', NULL, 1),
(7264171, 1129797, 13077, '<td valign="top">Beautiful building and well presented - good exposure, sharp throughout, and even has plenty of right angles to meet the challenge with.</td>', 'Beautiful building and well presented - good exposure, sharp throughout, and even has plenty of right angles to meet the challenge with.', '2014-09-18 20:09:31.000000', NULL, 1),
(7264172, 1129913, 13077, '<td valign="top">Nice perspective and composition.</td>', 'Nice perspective and composition.', '2014-09-18 20:10:01.000000', NULL, 1),
(7264173, 1129801, 13077, '<td valign="top">Looks like an interesting place, I''ll have to check back and see where it is.</td>', 'Looks like an interesting place, I''ll have to check back and see where it is.', '2014-09-18 20:11:52.000000', NULL, 1),
(7264174, 1129960, 13077, '<td valign="top">Nicely laid out and composed, and the tones look great.</td>', 'Nicely laid out and composed, and the tones look great.', '2014-09-18 20:12:27.000000', NULL, 1),
(7264175, 1129572, 13077, '<td valign="top">Shadows &amp; words nicely played.</td>', 'Shadows & words nicely played.', '2014-09-18 20:13:02.000000', NULL, 1),
(7264176, 1129892, 13077, '<td valign="top">Right angle? Yeah, more or less. Cool find and well captured.</td>', 'Right angle? Yeah, more or less. Cool find and well captured.', '2014-09-18 20:13:38.000000', NULL, 1),
(7264177, 1129979, 13077, '<td valign="top">I don''t think the blur adds anything to this one, honestly...</td>', 'I don''t think the blur adds anything to this one, honestly...', '2014-09-18 20:13:53.000000', NULL, 1),
(7264178, 1129930, 13077, '<td valign="top">I like the dramatic light and textures, would have worked well for that shadows challenge too.</td>', 'I like the dramatic light and textures, would have worked well for that shadows challenge too.', '2014-09-18 20:14:12.000000', NULL, 1),
(7264179, 1129586, 13077, '<td valign="top">I don''t really get a right-angle impression from this one.</td>', 'I don''t really get a right-angle impression from this one.', '2014-09-18 20:14:30.000000', NULL, 1),
(7264180, 1129719, 13077, '<td valign="top">Great detail in the bricks and the contrasting textures and shapes. I like it a lot.</td>', 'Great detail in the bricks and the contrasting textures and shapes. I like it a lot.', '2014-09-18 20:20:03.000000', NULL, 1),
(7264181, 1129692, 13077, '<td valign="top">Bold composition. It works well in my opinion.</td>', 'Bold composition. It works well in my opinion.', '2014-09-18 20:20:45.000000', NULL, 1),
(7264182, 1129683, 13077, '<td valign="top">Wow. Almost like an optical illusion, really cool.</td>', 'Wow. Almost like an optical illusion, really cool.', '2014-09-18 20:22:19.000000', NULL, 1),
(7264183, 1129985, 13077, '<td valign="top">I see your reflection... is that an X100? Nice street shot and a good expression captured on the lady''s face, but the right angles seem inconsequential in my opinion.</td>', 'I see your reflection... is that an X100? Nice street shot and a good expression captured on the lady''s face, but the right angles seem inconsequential in my opinion.', '2014-09-18 20:24:16.000000', NULL, 1),
(7264184, 1129899, 13077, '<td valign="top">Interesting - simple composition, and I think the grainy look works well here.</td>', 'Interesting - simple composition, and I think the grainy look works well here.', '2014-09-18 20:24:43.000000', NULL, 1),
(7264185, 1129738, 13077, '<td valign="top">Great find, such a visually exciting building. Nicely presented for sure. I like the blue border.</td>', 'Great find, such a visually exciting building. Nicely presented for sure. I like the blue border.', '2014-09-18 20:25:22.000000', NULL, 1),
(7264186, 1129945, 13077, '<td valign="top">Makes me thirsty. lol</td>', 'Makes me thirsty. lol', '2014-09-18 20:25:42.000000', NULL, 1),
(7264187, 1129927, 13077, '<td valign="top">Nice handling of the lighting conditions, and the sky looks so cool like that. I really like this.</td>', 'Nice handling of the lighting conditions, and the sky looks so cool like that. I really like this.', '2014-09-18 20:26:15.000000', NULL, 1),
(7264256, 1129930, 98565, '<td valign="top">this would have been perfect for the shadows challenge!</td>', 'this would have been perfect for the shadows challenge!', '2014-09-19 03:04:33.000000', NULL, 1),
(7264257, 1129683, 98565, '<td valign="top">gorgeous shot - the upper left corner is somewhat distracting though... a liitle warping would make it even better</td>', 'gorgeous shot - the upper left corner is somewhat distracting though... a liitle warping would make it even better', '2014-09-19 03:07:30.000000', NULL, 1);
