(7265330, 1129975, 61396, '<td valign="top">nice</td>', 'nice', '2014-09-23 04:33:39.000000', NULL, 1),
(7265331, 1129692, 61396, '<td valign="top">well cropped</td>', 'well cropped', '2014-09-23 04:35:40.000000', NULL, 1),
(7265339, 1129962, 61396, '<td valign="top">must be depression <br/> <br/>p.s. nicely framed, and even the cookies are rightly oriented.</td>', 'must be depression  p.s. nicely framed, and even the cookies are rightly oriented.', '2014-09-23 08:03:53.000000', NULL, 1),
(7265340, 1129693, 61396, '<td valign="top">a nice addition to your recent series of meaningful abstracts</td>', 'a nice addition to your recent series of meaningful abstracts', '2014-09-23 08:05:32.000000', NULL, 1),
(7265341, 1129683, 61396, '<td valign="top">well placed</td>', 'well placed', '2014-09-23 08:06:48.000000', NULL, 1),
(7265342, 1129696, 61396, '<td valign="top">a morning mystery?</td>', 'a morning mystery?', '2014-09-23 08:07:49.000000', NULL, 1),
(7265350, 1129896, 30364, '<td valign="top">It''s interesting, in a deliberately not interesting kind of way.  It''s a bit like the photographic version of a bit of stream-of-consciousness prose.  Some fragment of Samuel Beckett, maybe.  Or maybe it''s a photograph of nothing at all, which is even better, and even more interesting.  Thank you.</td>', 'It''s interesting, in a deliberately not interesting kind of way.  It''s a bit like the photographic version of a bit of stream-of-consciousness prose.  Some fragment of Samuel Beckett, maybe.  Or maybe it''s a photograph of nothing at all, which is even better, and even more interesting.  Thank you.', '2014-09-23 09:37:34.000000', NULL, 1),
(7265351, 1129900, 30364, '<td valign="top">That''s very nice, but the longer I looked at it the less interesting it became.  Not your fault; I just looked at it for too long.  Anyway, even at that it''s better than most.  Thank you.</td>', 'That''s very nice, but the longer I looked at it the less interesting it became.  Not your fault; I just looked at it for too long.  Anyway, even at that it''s better than most.  Thank you.', '2014-09-23 09:40:41.000000', NULL, 1),
(7265352, 1129707, 30364, '<td valign="top">Suddenly, nothing happened.  And that''s always an interesting photograph.  Thank you.</td>', 'Suddenly, nothing happened.  And that''s always an interesting photograph.  Thank you.', '2014-09-23 09:51:23.000000', NULL, 1),
(7265353, 1129916, 30364, '<td valign="top">Arbitrary geometry, and a title to match.  That''s fun, and interesting.  Thank you.</td>', 'Arbitrary geometry, and a title to match.  That''s fun, and interesting.  Thank you.', '2014-09-23 09:53:57.000000', NULL, 1),
(7265354, 1129870, 30364, '<td valign="top">Very nice tones, shapes and a good eye too.  As well as a willingness to stoop to anything.  Just kidding.  It''s lovely.  Could be by Henry Foster and that''s no faint praise. Thank you.</td>', 'Very nice tones, shapes and a good eye too.  As well as a willingness to stoop to anything.  Just kidding.  It''s lovely.  Could be by Henry Foster and that''s no faint praise. Thank you.', '2014-09-23 09:56:17.000000', NULL, 1),
(7265355, 1129927, 30364, '<td valign="top">Nice light.  Makes the effort of looking so sharply upward all worthwhile.  Thank you.</td>', 'Nice light.  Makes the effort of looking so sharply upward all worthwhile.  Thank you.', '2014-09-23 09:57:56.000000', NULL, 1),
(7265357, 1129899, 30364, '<td valign="top">Nice.  Not offensive at all.  There''s a sort of Wesleyan systematism to it, so the title''s elegantly apt.  Thank you.</td>', 'Nice.  Not offensive at all.  There''s a sort of Wesleyan systematism to it, so the title''s elegantly apt.  Thank you.', '2014-09-23 10:01:56.000000', NULL, 1),
(7265359, 1129696, 30364, '<td valign="top">Impossible to not enjoy this.  Thank you.</td>', 'Impossible to not enjoy this.  Thank you.', '2014-09-23 10:02:55.000000', NULL, 1),
(7265360, 1129985, 30364, '<td valign="top">Lovely candid portrait, but much diminished by the right angle.  But I know you had no choice; better to be right than good!  Thank you.</td>', 'Lovely candid portrait, but much diminished by the right angle.  But I know you had no choice; better to be right than good!  Thank you.', '2014-09-23 10:05:31.000000', NULL, 1),
(7265361, 1129693, 30364, '<td valign="top">That''s just silly.  I enjoyed it best of the bunch.  My top scorer.  Thank you.</td>', 'That''s just silly.  I enjoyed it best of the bunch.  My top scorer.  Thank you.', '2014-09-23 10:06:54.000000', NULL, 1),
(7265372, 1129692, 177704, '<td valign="top">cool</td>', 'cool', '2014-09-23 11:14:13.000000', NULL, 1),
(7265389, 1129683, 19825, '<td valign="top">This is excellent. I might have tried PS''s Perspective Warp to square thing up on this. But, I have to admit I am a bit compulsive on this.</td>', 'This is excellent. I might have tried PS''s Perspective Warp to square thing up on this. But, I have to admit I am a bit compulsive on this.', '2014-09-23 12:29:50.000000', NULL, 1),
(7265390, 1129990, 19825, '<td valign="top">Gotta bump this. Sweet candid and nice framing/composition.</td>', 'Gotta bump this. Sweet candid and nice framing/composition.', '2014-09-23 12:31:05.000000', NULL, 1),
(7265394, 1129914, 19825, '<td valign="top">This is fantastic. I love the angles, shadows, and the cat on his/her side. Very nicely done.</td>', 'This is fantastic. I love the angles, shadows, and the cat on his/her side. Very nicely done.', '2014-09-23 12:39:45.000000', NULL, 1),
(7265396, 1129962, 19825, '<td valign="top">Sweet shot. Perpendicular pups.</td>', 'Sweet shot. Perpendicular pups.', '2014-09-23 12:40:49.000000', NULL, 1),
(7265397, 1129692, 19825, '<td valign="top">Fascinating image. Beautifully done.</td>', 'Fascinating image. Beautifully done.', '2014-09-23 12:41:39.000000', NULL, 1),
(7265455, 1129927, 156466, '<td valign="top">Really like this.  Can''t find that look in a small town - I tried. :)</td>', 'Really like this.  Can''t find that look in a small town - I tried. :)', '2014-09-23 15:39:39.000000', NULL, 1),
(7265456, 1129976, 156466, '<td valign="top">I like the combination of hard angles and grain, but I''m not crazy about the level of "glow".  Shadow across the top is a little distracting as well.</td>', 'I like the combination of hard angles and grain, but I''m not crazy about the level of "glow".  Shadow across the top is a little distracting as well.', '2014-09-23 15:40:39.000000', NULL, 1),
(7265457, 1129797, 156466, '<td valign="top">Part of me wishes you''d moved a touch forward to lose the doorway one floor up and gained a bit of the railing on the next level, but I suspect that wasn''t entire possible.  Great place to shoot.</td>', 'Part of me wishes you''d moved a touch forward to lose the doorway one floor up and gained a bit of the railing on the next level, but I suspect that wasn''t entire possible.  Great place to shoot.', '2014-09-23 15:42:23.000000', NULL, 1),
(7265458, 1129895, 156466, '<td valign="top">Neat shot and there are plenty of right angles in there, but the skewed lines just get noisy for me.  Still a nice shot.</td>', 'Neat shot and there are plenty of right angles in there, but the skewed lines just get noisy for me.  Still a nice shot.', '2014-09-23 15:43:49.000000', NULL, 1),
(7265460, 1129707, 156466, '<td valign="top">Interesting use of wide angle perspective warping with right angles.</td>', 'Interesting use of wide angle perspective warping with right angles.', '2014-09-23 15:44:35.000000', NULL, 1),
(7265461, 1129975, 156466, '<td valign="top">I generally like perspective modification like this, but the cart doesn''t work for me with this for me.  Still a nice shot. 6</td>', 'I generally like perspective modification like this, but the cart doesn''t work for me with this for me.  Still a nice shot. 6', '2014-09-23 15:46:05.000000', NULL, 1),
(7265462, 1129683, 156466, '<td valign="top">Liked it immediately.  Loved it when I saw the figure.  Great optical illusion qualities.  Very nice.</td>', 'Liked it immediately.  Loved it when I saw the figure.  Great optical illusion qualities.  Very nice.', '2014-09-23 15:47:26.000000', NULL, 1),
(7265464, 1129954, 156466, '<td valign="top">Should have changed the strings get consistent lighting along the length since they''re your only angles.  A, D and G-strings almost disappear from the 14th fret on up.</td>', 'Should have changed the strings get consistent lighting along the length since they''re your only angles.  A, D and G-strings almost disappear from the 14th fret on up.', '2014-09-23 15:50:08.000000', NULL, 1),
(7265466, 1129692, 156466, '<td valign="top">Cool shot.  Would have liked a little more emphasis on the tiles to give you the right angles.</td>', 'Cool shot.  Would have liked a little more emphasis on the tiles to give you the right angles.', '2014-09-23 15:52:51.000000', NULL, 1),
(7265468, 1129984, 156466, '<td valign="top">Paper got sloppy, eh?</td>', 'Paper got sloppy, eh?', '2014-09-23 15:53:22.000000', NULL, 1),
(7265469, 1129902, 156466, '<td valign="top">A little better lighting on the right set of piggies would have been appreciated.</td>', 'A little better lighting on the right set of piggies would have been appreciated.', '2014-09-23 15:54:02.000000', NULL, 1),
(7265471, 1129801, 156466, '<td valign="top">I so want you to be 6 inches further left.</td>', 'I so want you to be 6 inches further left.', '2014-09-23 15:55:16.000000', NULL, 1),
(7265472, 1129925, 156466, '<td valign="top">When is an angle just a line?</td>', 'When is an angle just a line?', '2014-09-23 15:56:58.000000', NULL, 1),
(7265474, 1129786, 156466, '<td valign="top">Over painterly</td>', 'Over painterly', '2014-09-23 15:57:49.000000', NULL, 1),
(7265476, 1129935, 156466, '<td valign="top">Not crazy about the perspective through the hole.  It is a hole, right?</td>', 'Not crazy about the perspective through the hole.  It is a hole, right?', '2014-09-23 15:59:11.000000', NULL, 1),
(7265477, 1129958, 156466, '<td valign="top">Really not crazy about the tinting.  You did tint this, right?</td>', 'Really not crazy about the tinting.  You did tint this, right?', '2014-09-23 16:00:24.000000', NULL, 1),
(7265478, 1129870, 156466, '<td valign="top">Would love some perspective correction with all the skewed verticals.</td>', 'Would love some perspective correction with all the skewed verticals.', '2014-09-23 16:01:54.000000', NULL, 1),
(7265490, 1129786, 135744, '<td valign="top">Love the processing on this one!!</td>', 'Love the processing on this one!!', '2014-09-23 17:11:28.000000', NULL, 1),
(7265501, 1129786, 177322, '<td valign="top">Absolutely love this photo: the composition, the colors, your treatment, the beefy vehicle, that really cool feline! I mean REALLY COOL CAT!  (Great harness - wish I could find something like that for my big tomcat.)  Regrettably, I''m struggling to understand how it fits the "right angles produce the strength of the image" challenge. Nonetheless, on merits outside the parameters of the challenge:  two thumbs up!</td>', 'Absolutely love this photo: the composition, the colors, your treatment, the beefy vehicle, that really cool feline! I mean REALLY COOL CAT!  (Great harness - wish I could find something like that for my big tomcat.)  Regrettably, I''m struggling to understand how it fits the "right angles produce the strength of the image" challenge. Nonetheless, on merits outside the parameters of the challenge:  two thumbs up!', '2014-09-23 19:03:13.000000', NULL, 1),
(7265505, 1129683, 144271, '<td valign="top">Great pov</td>', 'Great pov', '2014-09-23 19:30:27.000000', NULL, 1),
(7265506, 1129870, 144271, '<td valign="top">I really like this angle</td>', 'I really like this angle', '2014-09-23 19:30:54.000000', NULL, 1),
(7265507, 1129697, 144271, '<td valign="top">Beautiful color in this one</td>', 'Beautiful color in this one', '2014-09-23 19:31:32.000000', NULL, 1),
(7265508, 1129921, 144271, '<td valign="top">Simple but very effective</td>', 'Simple but very effective', '2014-09-23 19:32:08.000000', NULL, 1),
(7265509, 1129572, 144271, '<td valign="top">I like the simplicity of this</td>', 'I like the simplicity of this', '2014-09-23 19:33:09.000000', NULL, 1),
(7265513, 1129975, 81362, '<td valign="top">I would have enjoyed this more turned 90 degrees counterclockwise. Current orientation does show right angles but sacrifices the rest of the composition in a way that feels contrived but not effective.</td>', 'I would have enjoyed this more turned 90 degrees counterclockwise. Current orientation does show right angles but sacrifices the rest of the composition in a way that feels contrived but not effective.', '2014-09-23 20:48:55.000000', NULL, 1),
(7265518, 1129683, 97225, '<td valign="top">Great display of right angles. The figure gives scale and context which would otherwise not be apparent. One of my ribbon choices.</td>', 'Great display of right angles. The figure gives scale and context which would otherwise not be apparent. One of my ribbon choices.', '2014-09-23 21:54:48.000000', NULL, 1),
(7265522, 1129844, 97225, '<td valign="top">Great display of right angles. I love the way the reflection becomes progressively more distorted the further it is from its source.</td>', 'Great display of right angles. I love the way the reflection becomes progressively more distorted the further it is from its source.', '2014-09-23 22:00:59.000000', NULL, 1),
(7265523, 1129927, 97225, '<td valign="top">A very compelling image.</td>', 'A very compelling image.', '2014-09-23 22:01:27.000000', NULL, 1),
(7265524, 1129697, 97225, '<td valign="top">Wow! You certainly chose the right angle to shoot this. Excellent.</td>', 'Wow! You certainly chose the right angle to shoot this. Excellent.', '2014-09-23 22:02:30.000000', NULL, 1),
