INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7265874, 1129692, 153814, '<td valign="top">I also mentioned the right angles "<i>I just <b>wish</b> there was more constrast with the right angles</i>".<br/>It wasn''t because I wanted to see more of them, I wanted to see this at or near the top and I was affraid it wouldn''t score well due to the lack of contrast in the right angles.<br/> <br/>That''s why it was a <b>wish.</b></td>', 'I also mentioned the right angles "I just wish there was more constrast with the right angles".It wasn''t because I wanted to see more of them, I wanted to see this at or near the top and I was affraid it wouldn''t score well due to the lack of contrast in the right angles. That''s why it was a wish.', '2014-09-24 16:03:10.000000', NULL, 0),
